#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/button_base/button/drop_down_button/drop_down_button_values/drop_down_button_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// DropDownButton's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/drop_down_button.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Menu mode routes the whole button to the drop-down; split mode keeps a primary Click region and a disclosure region at drop_down_edge. An unknown mode throws std::invalid_argument and changes nothing.
template <typename Declaring>
struct DropDownButtonDropDownModeCapability {
    PropertyCell<DropDownButtonMode, DropDownButtonDropDownModeCapability<Declaring>> drop_down_mode{DropDownButtonMode::menu};

    static void assign(DropDownButtonDropDownModeCapability& capability, DropDownButtonMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.drop_down_mode), incoming);
        if (!capability.drop_down_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.drop_down_mode));
    }
};

// The disclosure extent on drop_down_edge, 12 to 64 (default 16); a write moves the reserved content inset with it, so author primary-content padding after it. A value outside that range throws std::invalid_argument and changes nothing.
template <typename Declaring>
struct DropDownButtonDropDownWidthCapability {
    PropertyView<double, DropDownButtonDropDownWidthCapability<Declaring>> drop_down_width;

    static void assign(DropDownButtonDropDownWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.drop_down_width), std::move(incoming));
    }

    static double read(const DropDownButtonDropDownWidthCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.drop_down_width);
        return current;
    }
};

// The edge holding the disclosure region, right (default) or bottom; a write moves the reserved content inset to it. An unknown edge throws std::invalid_argument and changes nothing.
template <typename Declaring>
struct DropDownButtonDropDownEdgeCapability {
    PropertyView<DropDownButtonEdge, DropDownButtonDropDownEdgeCapability<Declaring>> drop_down_edge;

    static void assign(DropDownButtonDropDownEdgeCapability& capability, DropDownButtonEdge incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.drop_down_edge), std::move(incoming));
    }

    static DropDownButtonEdge read(const DropDownButtonDropDownEdgeCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        DropDownButtonEdge current = control.read_view(capability.drop_down_edge);
        return current;
    }
};

// Every DropDownButton capability, in the order the declaring class takes them.
template <typename Declaring>
struct DropDownButtonCapabilities : public DropDownButtonDropDownModeCapability<Declaring>,
                                    public DropDownButtonDropDownWidthCapability<Declaring>,
                                    public DropDownButtonDropDownEdgeCapability<Declaring> {};

} // namespace gui_forms
